import ast,hashlib,difflib
from pathlib import Path
root=Path('/workspace')
parent=root.joinpath('history_g2_r0088_summary_newest_two_anchors.py').read_text()
child=root.joinpath('summary_terminal_bridge.py').read_text()
print('SOURCE_DIFF')
print(''.join(difflib.unified_diff(parent.splitlines(True),child.splitlines(True),fromfile='accepted_parent',tofile='terminal_bridge',n=3))[:18000])
print('STRUCTURAL_AUDIT')
p=ast.parse(parent);c=ast.parse(child)
def functions(tree):
 result={}
 for n in tree.body:
  if isinstance(n,(ast.FunctionDef,ast.ClassDef)):
   result[n.name]=n
 return result
pf,cf=functions(p),functions(c)
print('new definitions',sorted(set(cf)-set(pf)))
print('changed inherited definitions',[name for name in pf if ast.dump(pf[name],include_attributes=False)"'!=ast.dump(cf[name],include_attributes=False)])
pm={n.name:n for n in pf['"'Model'].body if isinstance(n,ast.FunctionDef)}
cm={n.name:n for n in cf['Model'].body if isinstance(n,ast.FunctionDef)}
print('changed Model methods',[name for name in pm if ast.dump(pm[name],include_attributes=False)"'!=ast.dump(cm[name],include_attributes=False)])
for n in ('"'forward','training_loss','_target_match_summary','_context_history_correction'):
 assert ast.dump(pm[n],include_attributes=False)==ast.dump(cm[n],include_attributes=False)
for path in sorted(root.glob('summary_terminal_*.py')):
 tree=ast.parse(path.read_text());compile(tree,str(path),'exec')
 imports=[]
 for n in ast.walk(tree):
  if isinstance(n,ast.Import):imports.extend(i.name for i in n.names)
  if isinstance(n,ast.ImportFrom):imports.append(n.module)
 assert all(i.split('.')[0] in ('torch','unirank') for i in imports)
 assert not any(isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id in ('open','eval','exec','__import__') for n in ast.walk(tree))
 print(path.name,'syntax/import/source audit passed',hashlib.sha256(path.read_bytes()).hexdigest())
PY"

